package org.mockito.internal.util.reflection;

import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;

@SuppressWarnings("unchecked")
public class GenericMaster {

    /**
     * Discovers the parameterized (generic) type declared on the given field.
     * When the field has no generic type information, Object.class is returned.
     *
     * @param field
     * @return
     */
    public Class getGenericType(Field field) {
        Type typeInfo = field.getGenericType();
        boolean isParameterized = typeInfo != null && typeInfo instanceof ParameterizedType;

        if (isParameterized) {
            Type[] typeArgs = ((ParameterizedType) typeInfo).getActualTypeArguments();
            Type firstArg = typeArgs[0];
            //nested generics are not resolved any further
            return (Class) firstArg;
        }

        return Object.class;
    }
}

